contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entrypoint for property-based checking
    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public payable {
        // No precondition on params: initialization may revert for AlreadyInitialized or FeeRateTooHigh.
        // We call initialize exactly once and observe public getters.

        // Read before-state that is observable
        bool beforeInitialized = c.initialized(); if (__ESBMC_reverted()) return;

        // Attempt initialize and capture whether it reverted
        bool reverted;
        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read observable state after attempt
        bool afterInitialized = c.initialized(); if (__ESBMC_reverted()) return;
        address baseToken = c.baseToken(); if (__ESBMC_reverted()) return;
        address nft = c.nft(); if (__ESBMC_reverted()) return;
        uint128 vb = c.virtualBaseTokenReserves(); if (__ESBMC_reverted()) return;
        uint128 vn = c.virtualNftReserves(); if (__ESBMC_reverted()) return;
        uint56 cf = c.changeFee(); if (__ESBMC_reverted()) return;
        uint16 fr = c.feeRate(); if (__ESBMC_reverted()) return;
        bytes32 mr = c.merkleRoot(); if (__ESBMC_reverted()) return;
        bool uso = c.useStolenNftOracle(); if (__ESBMC_reverted()) return;
        bool pr = c.payRoyalties(); if (__ESBMC_reverted()) return;

        // The general rule to assert:
        // - If the call reverted, then the contract must remain in its previous initialized state (cannot flip from false->true on revert).
        // - If the call did not revert, then initialized must be true and all public fields must equal the supplied args.
        // This asserts a strong observable postcondition of initialize.
        assert(
            // If reverted: initialized unchanged (especially cannot become true if before was false)
            (reverted && afterInitialized == beforeInitialized)
            ||
            // If succeeded: initialized true and public getters match inputs
            (!reverted && afterInitialized
                && baseToken == _baseToken
                && nft == _nft
                && vb == _virtualBaseTokenReserves
                && vn == _virtualNftReserves
                && cf == _changeFee
                && fr == _feeRate
                && mr == _merkleRoot
                && uso == _useStolenNftOracle
                && pr == _payRoyalties)
        );
    }

    receive() external payable {}
}

